SELECT 
FROM gt_risk_type_definition
WHERE org_id = #{orgId}

    AND risk_type_code LIKE CONCAT('%', #{riskTypeCode}, '%')


    AND risk_type_name LIKE CONCAT('%', #{riskTypeName}, '%')


    AND risk_category = #{riskCategory}


    AND impact_level = #{impactLevel}


    AND probability_level = #{probabilityLevel}


    AND is_enabled = #{isEnabled}

ORDER BY create_time DESC

SELECT 
FROM gt_risk_type_definition
WHERE risk_type_code = #{riskTypeCode} AND org_id = #{orgId}

SELECT COUNT(*)
FROM gt_risk_type_definition
WHERE risk_type_code = #{riskTypeCode} AND org_id = #{orgId}

    AND risk_type_id != #{excludeId}

SELECT 
FROM gt_risk_type_definition
WHERE org_id = #{orgId}

    AND risk_category = #{riskCategory}


    AND impact_level = #{impactLevel}


    AND is_enabled = #{isEnabled}

ORDER BY risk_level DESC, create_time DESC
